package com.campus.personnel.infrastructure.persistence;
import java.util.*; import com.campus.personnel.application.FacultyStaffManagementService.ConcurrentFacultyStaffModificationException; import com.campus.personnel.domain.*; import com.campus.personnel.infrastructure.persistence.entity.FacultyStaffEntity; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;
@Repository class FacultyStaffPersistenceAdapter implements FacultyStaffRepository{ private final FacultyStaffJpaRepository repo; FacultyStaffPersistenceAdapter(FacultyStaffJpaRepository r){repo=r;} @Transactional public FacultyStaffMember save(FacultyStaffMember m){return managed(repo.findById(m.id()).orElseGet(()->new FacultyStaffEntity(m.id())),m);} @Transactional public FacultyStaffMember saveMutation(FacultyStaffMember m,long v){FacultyStaffEntity e=repo.findByIdForUpdate(m.id()).orElseThrow();if(e.getRowVersion()!=v)throw new ConcurrentFacultyStaffModificationException();return managed(e,m);} private FacultyStaffMember managed(FacultyStaffEntity e,FacultyStaffMember m){e.update(m.personnelNumber(),m.fullName(),m.email(),m.personnelType(),m.organizationUnitId(),m.status());return map(repo.saveAndFlush(e));} @Transactional(readOnly=true) public Optional<FacultyStaffMember> findById(UUID id){return repo.findById(id).map(this::map);} @Transactional(readOnly=true) public boolean existsByPersonnelNumber(String n){return repo.existsByPersonnelNumber(n);} @Transactional(readOnly=true) public List<FacultyStaffMember> findAll(){return repo.findAll(org.springframework.data.domain.Sort.by("personnelNumber")).stream().map(this::map).toList();} private FacultyStaffMember map(FacultyStaffEntity e){return new FacultyStaffMember(e.getId(),e.getPersonnelNumber(),e.getFullName(),e.getEmail(),e.getPersonnelType(),e.getOrganizationUnitId(),e.getStatus(),e.getRowVersion(),e.getCreatedAt(),e.getUpdatedAt());} }
